#ifndef TESTS_FAKE_TOKENS_H
#define TESTS_FAKE_TOKENS_H

#include "ctx.h"
#include "lexer.h"
#include "parser_internal.h"  // parser_init, parser_run

#include <stddef.h>  // size_t

// Changes: counts source lines; FAKE_LINE_BREAK marks a line break the lexer
// reports by line number only.
/**
 * @brief Token source replaying a fixed token array, then EOF forever. A token
 * written without a line gets the current line: 1 at first, one more after
 * every EOL token (FAKE_LINE_BREAK is one).
 */
typedef struct {
  const Token* tokens;
  size_t count;
  size_t position;
  int breaks;
} FakeSource;

// Token type the fake source answers by throwing a lexical error, as the lexer
// does on a malformed lexeme
#define FAKE_LEXICAL_ERROR ((TokenType)1000)

// Changes: the line break is handed out as an EOL_TOKEN, as the lexer does.
// A line break inside parentheses: the fake source hands it out as an
// EOL_TOKEN, as the lexer does, and the token layer hides it
#define FAKE_LINE_BREAK ((TokenType)1001)

/**
 * @brief TokenSourceNext over a FakeSource, hands out heap copies of the text
 * as the real lexer would (the parser owns and frees them).
 *
 * @param[in] ctx Context the lexical error is thrown into
 * @param[in,out] state a FakeSource
 * @return next token, EOF_TOKEN once the array is exhausted
 * @throws E_LEXER_ERROR on a FAKE_LEXICAL_ERROR token
 */
Token fake_next(Ctx* ctx, void* state);

#define TOK(t) ((Token){.type = (t)})
#define IDENT_TOK(name) ((Token){.type = IDENT, .value.text = (name)})
#define INDENT_TOK(n) ((Token){.type = INDENT, .value.integer = (n)})

/**
 * @brief Creates a parser reading the given token array
 */
#define START(source, ...)                                                \
  do {                                                                    \
    static const Token tokens_[] = {__VA_ARGS__};                         \
    (source) = (FakeSource){.tokens = tokens_,                            \
                            .count = sizeof(tokens_) / sizeof(*tokens_)}; \
    parser_init(ctx, fake_next, &(source));                               \
  } while (0)

// === PROGRAM TOKENS ===
//
// A program is written one source line per row: an indented line starts with
// its raw indent LINE(n), as the lexer emits it, a line in column 0 has none,
// and every line ends with EOL.

#define LINE(n) INDENT_TOK(n)
#define EOL TOK(EOL_TOKEN)
#define ID(name) IDENT_TOK(name)
#define INT(n) ((Token){.type = NUMBER_INT, .value.integer = (n)})
#define DBL(d) ((Token){.type = NUMBER_DOUBLE, .value.decimal = (d)})
#define LEX_ERROR TOK(FAKE_LEXICAL_ERROR)
// Changes: new, a line break inside parentheses.
#define BREAK TOK(FAKE_LINE_BREAK)
#define STR(s) ((Token){.type = STRING, .value.text = (s)})
#define TSTR(s) ((Token){.type = TRIPLE_STRING, .value.text = (s)})
// Changes: `()` is the lexer's UNIT token.
#define UNIT_VALUE TOK(UNIT)

// Changes: the delimiters carry no text, as from the lexer.
#define S_OPEN TOK(S_STRING_START)
#define S_CLOSE TOK(S_STRING_END)
#define TS_OPEN TOK(TRIPLE_S_STRING_START)
#define TS_CLOSE TOK(TRIPLE_S_STRING_END)
#define DOLLAR_OPEN TOK(DOLLAR_EXPRESSION_START)
#define DOLLAR_CLOSE TOK(DOLLAR_EXPRESSION_END)

// `import ifj26.*` on its own line
#define PROLOG \
  TOK(IMPORT), ID("ifj26"), TOK(PERIOD), TOK(OPERATOR_MULTIPLY), EOL

// `def f() = <expression>` after the prolog
#define BODY(...) \
  PROLOG, TOK(DEF), ID("f"), UNIT_VALUE, TOK(ASSIGN), __VA_ARGS__, EOL

// `def f() =` header line ending in a line break, so the following lines
// (indented by 2) form a multi-line function body
#define DEF_F TOK(DEF), ID("f"), UNIT_VALUE, TOK(ASSIGN), EOL

/**
 * @brief Parses the given tokens as a whole program into ctx->ast
 */
#define PARSE(...)                                                          \
  do {                                                                      \
    static const Token program_[] = {__VA_ARGS__};                          \
    static FakeSource program_source_;                                      \
    program_source_ = (FakeSource){                                         \
        .tokens = program_, .count = sizeof(program_) / sizeof(*program_)}; \
    parser_run(ctx, fake_next, &program_source_);                           \
  } while (0)

#endif
